        "highlighted": "dotnet ef dbcontext scaffold \\\n  <span class=\"hljs-string\">&quot;Host=localhost;Database=app;Username=app;Password=...&quot;</span> \\\n  BlueTusk.EntityFrameworkCore \\\n  --context AppDbContext \\\n  --output-dir Models \\\n  --schema public\n",
